+/* AUD_ADC_FPORT returns one 32-bit word per sample period with ADCR in
+ * [31:16] and ADCL in [15:0], and the DMA must move those words whole
+ * (see capture_start_dma()).  The upper half is advertising 16-bit mono,
+ * so ADCR has to go: the vendor AP reference does exactly this in
+ * _onboard_mic_read() ("remove adcr data and remain adcl data").  Leaving
+ * the pairs in place would hand the recognizer two interleaved microphones
+ * at twice the configured rate, which nothing downstream can decode.
+ */
+
+static void capture_compact_mono(FAR struct ap_buffer_s *apb)
+{
+  FAR int16_t *samples = (FAR int16_t *)apb->samp;
+  uint32_t frames = (uint32_t)apb->nmaxbytes / 4u;
+  uint32_t i;
+
+  /* Forward in place: the source index 2*i is always ahead of i. */
+
+  for (i = 0; i < frames; i++)
+    {
+      samples[i] = samples[2 * i];
+    }
+
+  apb->nbytes = (uint32_t)apb->nmaxbytes / 2u;
+}
+
