11	export class StdioAcpAdapter {
12	  constructor({ backend, command, args = ["acp"], cwd = process.cwd(), env = process.env }) {
13	    this.backend = backend;
14	    this.command = command;
15	    this.args = args;
16	    this.cwd = cwd;
17	    this.env = env;
18	    this.listener = () => {};
19	    this.pending = new Map();
20	    this.tools = new Map();
21	    this.nextId = 1;
22	    this.child = null;
23	    /* What the backend says it can run, from the `models` block of session/new.
24	     * The device has no other source of truth: a list invented by the bridge
25	     * would offer names the backend refuses to run. */
26	    this.availableModels = [];
27	    this.modelId = null;
28	    /* Process liveness as last reported to the bridge. Kept here so a device
29	     * that reconnects learns the current truth from the next snapshot instead
30	     * of assuming "the bridge is up, so the agent must be too". */
31	    this.backendState = "unknown";
32	  }
