34	  onEvent(listener) { this.listener = listener; }
35	
36	  /* The bridge must not infer liveness from a live socket: the child can exit
37	   * while this process keeps running. exitCode stays null until exit, and a
38	   * killed-but-not-yet-reaped child is still a dead one. null before the first
39	   * start, so "not started" never reads as "died". */
40	  alive() {
41	    if (!this.child) return null;
42	    return Boolean(this.child.exitCode === null && !this.child.killed);
43	  }
