51	  async start() {
52	    this.child = spawn(this.command, this.args, { cwd: this.cwd, env: this.env, stdio: ["pipe", "pipe", "pipe"], detached: true });
53	    this.child.stderr.on("data", () => {}); // stderr is deliberately never forwarded to DeskMate Link.
54	    this.child.on("error", (error) => {
55	      for (const entry of this.pending.values()) entry.reject(error);
56	      this.pending.clear();
57	      this.#noteBackend("down");
58	      this.listener({ type: "text", text: "ACP backend unavailable" });
59	    });
60	    this.child.on("exit", () => {
61	      for (const entry of this.pending.values()) entry.reject(new Error("acp_process_exited"));
62	      this.pending.clear();
