78	  /* Start a fresh ACP session on the same backend process. A device
79	   * "new conversation" must begin a real backend context, otherwise the model
80	   * keeps answering with the previous conversation in view. */
81	  async newSession() {
82	    const created = await this.request("session/new", { cwd: this.cwd, mcpServers: [] });
83	    if (typeof created.sessionId === "string" && created.sessionId) {
84	      this.sessionId = created.sessionId;
85	    }
86	    /* A new session starts on the backend's default model, not on the one the
87	     * user picked. Re-applying the pick keeps "new conversation" from also
88	     * meaning "silently back to the default model". */
89	    const wanted = this.modelId;
90	    this.#syncModels(created);
91	    if (wanted && wanted !== this.modelId) {
92	      try { await this.setModel(wanted); } catch { /* keep the backend default */ }
93	    }
94	    this.listener({ type: "session_started", backend: this.backend, sessionId: this.sessionId });
95	    return this.sessionId;
96	  }
