98	  /* session/new reports the models the backend will actually run. Variants
99	   * (".../high") are real ids too, but the device's list is a short numbered
100	   * picker; keeping base ids keeps every entry a distinct model. */
101	  #syncModels(created) {
102	    const models = created?.models;
103	    if (!models || typeof models !== "object") return;
104	    if (typeof models.currentModelId === "string" && models.currentModelId) {
105	      this.modelId = models.currentModelId;
106	    }
107	    if (!Array.isArray(models.availableModels)) return;
108	    const seen = new Set();
109	    const options = [];
110	    for (const entry of models.availableModels) {
111	      const id = entry?.modelId;
112	      if (typeof id !== "string" || !id) continue;
113	      if (/\/(low|medium|high|xhigh|max)$/.test(id)) continue;
114	      if (seen.has(id)) continue;
115	      seen.add(id);
116	      options.push(id);
117	    }
118	    if (options.length === 0) return;
119	    /* Current first: the device cycles in this order, so the default model is
120	     * the first thing its key offers. */
121	    if (this.modelId && seen.has(this.modelId)) {
122	      options.splice(options.indexOf(this.modelId), 1);
123	      options.unshift(this.modelId);
124	    }
125	    this.availableModels = options;
126	    this.listener({ type: "models", current: this.modelId, options });
127	  }
