183	      return;
184	    }
185	    if (message.id !== undefined && message.method === "session/request_permission") {
186	      const toolCall = message.params?.toolCall ?? {};
187	      const cached = this.tools.get(toolCall.toolCallId);
188	      this.listener({ type: "permission_request", params: { ...message.params, requestId: message.id, toolCall: { ...cached, ...toolCall, rawInput: toolCall.rawInput ?? cached?.rawInput } } });
189	      return;
190	    }
191	    if (message.id !== undefined && message.method) {
192	      this.send({ jsonrpc: "2.0", id: message.id, error: { code: -32601, message: "DeskMate bridge does not implement this ACP client request" } });
193	      return;
194	    }
195	    if (message.method === "_kiro.dev/metadata") {
196	      this.#normalizeKiroMetadata(message.params);
197	      return;
198	    }
199	    if (message.method === "session/update" || message.method === "_kiro.dev/session/update") {
200	      this.#normalize(message.params?.update, message.params?.sessionId);
201	    }
202	  }
