204	  #recordPromptUsage(entry, result) {
205	    if (entry.method !== "session/prompt") return;
206	    const usage = result?.usage;
207	    if (!usage || typeof usage !== "object") return;
208	    const input = usage.inputTokens;
209	    const output = usage.outputTokens;
210	    const total = usage.totalTokens;
211	    if (![input, output, total].every((value) => typeof value === "number" && Number.isFinite(value) && value >= 0)) return;
212	    this.listener({ type: "usage", tokens: { input, output, total } });
213	  }
214	
215	  #normalizeKiroMetadata(params = {}) {
216	    if (params.sessionId && this.sessionId && params.sessionId !== this.sessionId) return;
217	    const values = Array.isArray(params.meteringUsage) ? params.meteringUsage : [];
218	    const credits = values.reduce((sum, entry) => {
219	      if (entry?.unit !== "credit" || typeof entry.value !== "number" || !Number.isFinite(entry.value) || entry.value < 0) return sum;
220	      return sum + entry.value;
221	    }, 0);
222	    const hasCredits = values.some((entry) => entry?.unit === "credit" && typeof entry.value === "number" && Number.isFinite(entry.value) && entry.value >= 0);
223	    const percentage = params.contextUsagePercentage;
224	    const context = typeof percentage === "number" && Number.isFinite(percentage) && percentage >= 0
225	      ? { unit: "percent", used: percentage, limit: 100 }
226	      : undefined;
227	    if (hasCredits || context) {
228	      this.listener({
229	        type: "usage",
230	        ...(hasCredits ? { charge: { kind: "credit", amount: credits, unit: "credits" } } : {}),
231	        ...(context ? { context } : {}),
232	      });
233	    }
234	  }
235	
236	  #normalize(update = {}, sessionId) {
237	    const type = update.sessionUpdate;
238	    if (type === "agent_message_chunk") {
239	      const text = update.content?.text;
240	      if (typeof text === "string" && text) this.listener({ type: "text", text });
241	      return;
242	    }
243	    if (type === "usage_update") {
244	      const used = update.used;
245	      const limit = update.size;
246	      if (sessionId === this.sessionId && typeof used === "number" && Number.isFinite(used) && used >= 0 && typeof limit === "number" && Number.isFinite(limit) && limit >= 0) {
247	        this.listener({ type: "usage", context: { unit: "token", used, limit } });
248	      }
249	      return;
250	    }
251	    if (type === "tool_call" || type === "tool_call_update") {
252	      const previous = this.tools.get(update.toolCallId) ?? {};
253	      this.tools.set(update.toolCallId, { ...previous, ...update, rawInput: update.rawInput ?? previous.rawInput });
254	      const status = update.status;
255	      this.listener({ type: "tool", toolCallId: update.toolCallId, title: update.title ?? previous.title ?? "Tool activity", status: status === "completed" || status === "failed" ? status : "in_progress" });
256	    } else if (type === "tool_call_chunk") {
257	      const previous = this.tools.get(update.toolCallId) ?? {};
258	      this.tools.set(update.toolCallId, { ...previous, ...update });
259	      this.listener({ type: "tool", toolCallId: update.toolCallId, title: update.title ?? previous.title ?? "Tool activity", status: "in_progress" });
260	    }
261	  }
262	}
