264	export function adapterFor(backend, options = {}) {
265	  if (backend === "mimo") {
266	    /* MiMoCode 0.1.14 never answers `initialize` while any external plugin is
267	     * installed under ~/.config/mimocode/plugins — even an empty one. --pure
268	     * skips external plugins (mirrors src/stdio-verifier.js); set
269	     * DESKMATE_MIMO_PURE=0 to spawn without it when debugging plugins. */
270	    const args = options.args ?? ["acp"];
271	    const withPure = process.env.DESKMATE_MIMO_PURE === "0" || args.includes("--pure") ? args : [...args, "--pure"];
272	    return new StdioAcpAdapter({ backend, command: process.env.DESKMATE_MIMO_BIN || "mimo", ...options, args: withPure });
273	  }
274	  if (backend === "kiro") return new StdioAcpAdapter({ backend, command: process.env.DESKMATE_KIRO_BIN || "kiro-cli", ...options });
275	  throw new TypeError("backend must be fake, mimo, or kiro");
276	}
