26	function splitOutput(message) {
27	  const pieces = [];
28	  let piece = "";
29	  for (const character of message) {
30	    const candidate = piece + character;
31	    /* JSON may double every source byte through escaping. Keeping source
32	     * chunks at 1600 bytes leaves space for all protocol fields under 4 KiB. */
33	    if (candidate !== piece && Buffer.byteLength(candidate, "utf8") <= 1600) {
34	      piece = candidate;
35	    } else {
36	      if (piece) pieces.push(piece);
37	      piece = character;
38	    }
39	  }
40	  if (piece) pieces.push(piece);
41	  return pieces;
