534	        if ((event.status === "completed" || event.status === "failed") && this.nonce) {
535	          this.publish({ v: VERSION, type: "tool_result", connection_nonce: this.nonce, epoch: this.epoch, toolCallId: event.toolCallId, status: event.status });
536	        }
537	        return;
538	      }
539	      if (event.type === "text") {
540	        this.#queueOutput(event.text);
541	        this.textBuffer += event.text;
542	        if (this.textTimer) return;
543	        this.textTimer = setTimeout(() => {
544	          this.facts.msg = summarizeMessage(this.textBuffer);
545	          this.textBuffer = "";
546	          this.textTimer = null;
547	          this.snapshot();
548	        }, 120);
549	        this.textTimer.unref?.();
550	      }
551	    } finally {
552	      try { this.onAdapterEvent(event, this.currentUsage()); } catch {}
553	    }
554	  }
555	}
