1	export class FakeAcpAdapter {
2	  constructor() {
3	    this.backend = "fake";
4	    this.listener = () => {};
5	    this.responses = [];
6	    this.submits = [];
7	    this.submitHandler = null;
8	    this.backendState = "unknown";
9	    this.sessionSeq = 0;
10	    this.sessionId = null;
11	  }
12	  onEvent(listener) { this.listener = listener; }
13	  alive() { return this.backendState === "unknown" ? null : this.backendState === "up"; }
14	  #noteBackend(state) {
15	    if (this.backendState === state) return;
16	    this.backendState = state;
17	    this.listener({ type: "backend_state", state });
18	  }
19	  #newSessionId() {
20	    this.sessionSeq += 1;
21	    this.sessionId = `fake-session-${this.sessionSeq}`;
22	    return this.sessionId;
23	  }
24	  async start() { this.#newSessionId(); this.listener({ type: "session_started", backend: this.backend, sessionId: this.sessionId }); this.listener({ type: "text", text: "Agent ready" }); this.#noteBackend("up"); }
25	  /* Same contract as the real adapter: a new conversation is a new backend
26	   * session, announced the same way so the bridge's generation bookkeeping is
27	   * exercised identically against the fake backend. */
28	  async newSession() {
29	    this.#newSessionId();
30	    this.listener({ type: "session_started", backend: this.backend, sessionId: this.sessionId });
31	    return this.sessionId;
32	  }
33	  selectSession(sessionId) { this.sessionId = sessionId; return this.sessionId; }
34	  async submit(text) {
35	    this.submits.push(text);
36	    if (this.submitHandler) return this.submitHandler(text);
37	    /* Mirror the real backend: stream a transcript so device-side output
38	     * handling (agent_output -> turn transcript) is exercised without mimo. */
39	    this.text(`(fake) done: ${text}\nhello world script written to hello.sh`);
40	    return { stopReason: "completed" };
41	  }
42	  async respondPermission(id, result) { this.responses.push({ id, result }); }
43	  requestPermission(params) { this.listener({ type: "permission_request", params }); }
44	  text(text) { this.listener({ type: "text", text }); }
45	  tool(event) { this.listener({ type: "tool", ...event }); }
46	  usage(event) { this.listener({ type: "usage", ...event }); }
47	  async stop() { this.#noteBackend("down"); }
48	}
