203	      await this.adapter.respondPermission(result.id, result.result);
204	      this.facts.prompt = null;
205	      this.facts.waiting = 0;
206	      this.facts.running = this.activeTurn ? 1 : 0;
207	      this.facts.msg = "Permission decision accepted by ACP";
208	      this.#result(result.deviceResult.id, true);
209	      this.snapshot();
210	    } catch {
211	      this.#result(result.deviceResult.id, false, "acp_rejected");
212	    }
213	  }
