215	  async disconnect() {
216	    this.linkActive = false;
217	    clearTimeout(this.textTimer);
218	    this.textTimer = null;
219	    this.textBuffer = "";
220	    clearTimeout(this.outputTimer);
221	    this.outputTimer = null;
222	    this.outputBuffer = "";
223	    if (this.activeTurn?.device && this.activeTurn.nonce === this.nonce) {
224	      this.activeTurn.detached = true;
225	    }
226	    clearTimeout(this.permissionTimer);
227	    this.permissionTimer = null;
228	    const rejected = this.permissions.rejectPending();
229	    if (rejected) {
230	      try { await this.adapter.respondPermission(rejected.id, rejected.result); } catch {}
231	    }
232	    this.permissions.disconnect();
233	    this.facts.prompt = null;
234	    this.facts.waiting = 0;
235	  }
236	
237	  /* An unanswered prompt must not take the device link down with it. Dropping
238	   * the link here leaves the board showing an approval page whose decisions are
239	   * then discarded (`receive` ignores everything while the link is inactive),
240	   * so the prompt hangs until the ACP side gives up and the device only notices
241	   * minutes later when its own snapshot timeout expires. Deny through ACP
242	   * instead and publish a prompt-less snapshot: the page clears, the turn
243	   * unblocks, and the channel stays usable for the next one. */
244	  #armPermissionTimeout() {
245	    clearTimeout(this.permissionTimer);
246	    this.permissionTimer = setTimeout(() => {
247	      this.permissionTimer = null;
248	      const rejected = this.permissions.rejectPending();
249	      if (rejected) {
250	        try {
251	          const sent = this.adapter.respondPermission(rejected.id, rejected.result);
252	          if (sent && typeof sent.catch === "function") sent.catch(() => {});
253	        } catch {}
254	      }
255	      this.facts.prompt = null;
256	      this.facts.waiting = 0;
257	      this.facts.running = this.activeTurn ? 1 : 0;
258	      this.facts.msg = "Approval request expired";
259	      this.snapshot();
260	    }, this.permissionTimeoutMs);
261	  }
