316	
317	  async #receiveSession(message) {
318	    if (message.connection_nonce !== this.nonce || message.epoch !== this.epoch) return;
319	
320	    if (message.cmd === "session_list") return this.sessionListSnapshot();
321	
322	    if (message.cmd === "session_switch") {
323	      /* The device sends the generation number it wants; older generations are
324	       * still live on the backend process, so switching is re-pointing this
325	       * bridge at a session it already holds. */
326	      const target = this.generations.find((entry) => entry.id === message.target);
327	      if (!target || target.acpSessionId === null ||
328	          typeof this.adapter.selectSession !== "function") {
329	        return this.sessionListSnapshot();
330	      }
331	      this.adapter.selectSession(target.acpSessionId);
332	      this.currentSession = target.id;
333	      this.facts.msg = `Session ${target.id} selected`;
334	      this.sessionListSnapshot();
335	      this.snapshot();
336	      return;
337	    }
338	
339	    /* session_new. A turn belongs to the session it was started in, so a new
340	     * one is refused while the old one is still running: the unchanged listing
341	     * keeps the previous generation current, which the device reads as "not
342	     * yet" rather than as a new session. */
343	    if (this.activeTurn || this.facts.waiting > 0) return this.sessionListSnapshot();
344	    if (typeof this.adapter.newSession !== "function") return this.sessionListSnapshot();
345	
346	    const before = this.generation;
347	    try {
348	      await this.adapter.newSession();
349	    } catch {
350	      return this.sessionListSnapshot();
351	    }
352	    /* A well-behaved adapter announces session_started, which already recorded
353	     * the generation; this covers an adapter that does not. */
354	    if (this.generation === before) {
355	      this.#recordGeneration(this.adapter.attachSession?.() ?? null);
356	    }
357	    this.facts.msg = "New session started";
358	    this.snapshot();
359	  }
360	
361	  #startTurn({ text, device, requestId = null, nonce = null, epoch: turnEpoch = null }) {
362	    const turn = {
363	      id: turnId(), device, requestId, nonce, epoch: turnEpoch, outputSeq: 0, detached: false,
364	    };
365	    this.activeTurn = turn;
366	    this.facts.running = 1;
367	    this.facts.msg = "Agent working";
368	    if (this.nonce) this.snapshot();
369	    const completion = Promise.resolve().then(() => this.adapter.submit(text));
370	    completion.then(
371	      (result) => this.#finishTurn(turn, "completed", result?.stopReason),
372	      () => this.#finishTurn(turn, "failed", "backend_unavailable"),
373	    );
374	    return { turn, completion };
375	  }
376	
377	  #finishTurn(turn, status, error) {
378	    this.#flushOutput(turn);
379	    if (this.activeTurn !== turn) return;
380	    this.activeTurn = null;
381	    this.facts.running = 0;
382	    this.facts.msg = status === "completed" ? "Agent turn completed" : "Agent turn failed";
383	    if (this.nonce) this.snapshot();
384	    if (this.#turnConnected(turn)) {
385	      const result = {
386	        v: VERSION, type: "turn_result", connection_nonce: turn.nonce, epoch: turn.epoch,
387	        request_id: turn.requestId, turn_id: turn.id, status,
388	        ...(status === "failed" ? { error } : {}),
389	      };
390	      const request = this.requestAcks.get(turn.requestId);
391	      if (request) request.result = result;
392	      this.#publishTurnResult(result);
393	    }
394	  }
395	
396	  #promptAck(requestId, accepted, error) {
397	    if (typeof requestId !== "string" ||
398	        Buffer.byteLength(requestId, "utf8") > MAX_REQUEST_ID_BYTES ||
399	        !this.linkActive || !this.nonce) return;
400	    this.publish(assertFits({
401	      v: VERSION, type: "prompt_ack", connection_nonce: this.nonce, epoch: this.epoch,
402	      request_id: requestId, accepted, ...(error ? { error } : {}),
403	    }));
404	  }
405	
406	  #publishPromptAck(ack) {
407	    if (!this.linkActive || !this.nonce) return;
408	    this.publish(assertFits({
409	      v: VERSION, type: "prompt_ack", connection_nonce: this.nonce, epoch: this.epoch,
410	      request_id: ack.requestId, accepted: ack.accepted,
411	      ...(ack.accepted ? { turn_id: ack.turnId } : {}),
412	    }));
413	  }
414	
415	  #publishTurnResult(result) {
416	    if (this.linkActive && result.connection_nonce === this.nonce && result.epoch === this.epoch) {
417	      this.publish(assertFits(result));
418	    }
419	  }
420	
421	  #turnConnected(turn) {
422	    return turn.device && !turn.detached && turn.nonce === this.nonce && turn.epoch === this.epoch;
423	  }
424	
425	  #queueOutput(text) {
426	    const turn = this.activeTurn;
427	    if (!turn || !this.#turnConnected(turn)) return;
428	    this.outputBuffer += sanitizeAgentText(text);
429	    if (!this.outputBuffer || this.outputTimer) return;
430	    this.outputTimer = setTimeout(() => this.#flushOutput(turn), this.outputFlushMs);
431	    this.outputTimer.unref?.();
432	  }
433	
434	  #flushOutput(turn = this.activeTurn) {
435	    if (!this.outputBuffer || !turn || this.activeTurn !== turn) return;
436	    clearTimeout(this.outputTimer);
437	    this.outputTimer = null;
438	    const text = this.outputBuffer;
439	    this.outputBuffer = "";
440	    if (!this.#turnConnected(turn)) return;
441	    for (const chunk of splitOutput(text)) {
442	      const message = {
443	        v: VERSION, type: "agent_output", connection_nonce: turn.nonce, epoch: turn.epoch,
444	        request_id: turn.requestId, turn_id: turn.id, output_seq: ++turn.outputSeq, text: chunk,
445	      };
446	      if (byteLength(message) > 4096) throw new RangeError("agent output exceeds 4096 UTF-8 bytes");
447	      this.publish(message);
448	    }
449	  }
450	
451	  #result(id, accepted, error) {
452	    if (!this.linkActive || !this.nonce || typeof id !== "string" ||
453	        Buffer.byteLength(id, "utf8") > MAX_REQUEST_ID_BYTES) return;
454	    try {
455	      this.publish(assertFits({
456	        v: VERSION, type: "permission_result", connection_nonce: this.nonce,
457	        epoch: this.epoch, id, accepted, ...(error ? { error } : {}),
458	      }));
459	    } catch {
460	      /* An invalid device ID must not make bridge output exceed the link cap. */
461	    }
462	  }
463	
464	  #onAdapterEvent(event) {
465	    try {
466	      if (event.type === "text") {
467	        event = { ...event, text: sanitizeAgentText(event.text) };
468	      }
469	      if (event.type === "backend_state") {
470	        const state = event.state === "up" ? "up" : "down";
471	        if (this.facts.backend !== state) {
472	          this.facts.backend = state;
473	          this.facts.msg = state === "up" ? "Coding agent ready" : "Coding agent exited";
474	          this.snapshot();
475	        }
476	        return;
477	      }
478	      if (event.type === "session_started") {
479	        /* Every session the backend actually starts is a generation, whether
480	         * it came from startup or from a device `rnew`. */
481	        this.#recordGeneration(event.sessionId ?? this.adapter.attachSession?.() ?? null);
482	        this.usage.reset(event.backend ?? this.adapter.backend);
483	        this.usageReady = true;
484	        this.usageSnapshot();
485	        return;
486	      }
487	      if (event.type === "usage") {
488	        this.usage.record(event);
489	        this.usageSnapshot();
490	        return;
491	      }
492	      if (event.type === "models") {
493	        /* The backend's own list wins over `--models`: only it knows what it
494	         * will actually run, and the device copies this list verbatim. */
495	        if (!Array.isArray(event.options)) return;
496	        const options = event.options.filter(validModelName).slice(0, 32);
497	        if (options.length === 0) return;
498	        this.modelOptions = options;
499	        this.modelCurrent = validModelName(event.current) && options.includes(event.current)
500	          ? event.current
501	          : options[0];
502	        this.modelsSnapshot();
503	        return;
504	      }
505	      if (event.type === "permission_request") {
506	        clearTimeout(this.permissionTimer);
507	        if (this.activeTurn?.device && this.activeTurn.detached) {
508	          /* The ACP turn belongs to a disconnected device. Do not rebind its
509	           * permission request to a later nonce; reject through ACP instead. */
510	          const orphaned = this.permissions.ptSubmit(event.params);
511	          const rejected = this.permissions.rejectPending();
512	          if (rejected) {
513	            this.adapter.respondPermission(rejected.id, rejected.result).catch(() => {});
514	          }
515	          return orphaned;
516	        }
517	        const snapshot = this.permissions.ptSubmit(event.params);
518	        this.facts = { ...this.facts, ...snapshot, msg: snapshot.msg };
519	        this.snapshot();
520	        this.#armPermissionTimeout();
521	        return;
522	      }
523	      if (event.type === "tool") {
524	        if (this.activeTurn?.device && this.activeTurn.detached) {
525	          /* This tool belongs to a turn started by the disconnected nonce. */
526	          return;
527	        }
528	        clearTimeout(this.textTimer);
529	        this.textBuffer = "";
530	        this.facts.running = this.activeTurn ? 1 :
531	          (event.status === "completed" || event.status === "failed" ? 0 : 1);
532	        this.facts.msg = summarizeMessage(event.title || "Tool activity");
533	        this.snapshot();
534	        if ((event.status === "completed" || event.status === "failed") && this.nonce) {
535	          this.publish({ v: VERSION, type: "tool_result", connection_nonce: this.nonce, epoch: this.epoch, toolCallId: event.toolCallId, status: event.status });
536	        }
537	        return;
538	      }
539	      if (event.type === "text") {
540	        this.#queueOutput(event.text);
541	        this.textBuffer += event.text;
542	        if (this.textTimer) return;
543	        this.textTimer = setTimeout(() => {
544	          this.facts.msg = summarizeMessage(this.textBuffer);
545	          this.textBuffer = "";
546	          this.textTimer = null;
547	          this.snapshot();
548	        }, 120);
549	        this.textTimer.unref?.();
550	      }
551	    } finally {
552	      try { this.onAdapterEvent(event, this.currentUsage()); } catch {}
553	    }
554	  }
555	}
